def t(lang: str, key: str, **kw) -> str:
    row = T.get(key)
    if row is None:
        return key
    text = row[_IDX.get(lang, 1)] or row[1]
    if kw:
        try:
            return text.format(**kw)
        except (KeyError, IndexError, ValueError):
            return text
    return text
